import * as THREE from 'three/webgpu';
import { Fn, uniform, instanceIndex, attribute, vec3, vec4, color, mix, float, positionLocal, smoothstep, cameraPosition, modelPosition } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'ParticleConstellationHero';
  group.position.set(0, 0, 0);

  const FIELD_COUNT = 1200;
  const CORE_COUNT = 90;
  const timelines = [];

  // ---------- helpers ----------
  function randInEllipsoid(rx, ry, rz) {
    let x, y, z, d;
    do {
      x = (Math.random() * 2 - 1);
      y = (Math.random() * 2 - 1);
      z = (Math.random() * 2 - 1);
      d = x * x + y * y + z * z;
    } while (d > 1 || d === 0);
    return new THREE.Vector3(x * rx, y * ry, z * rz);
  }

  function randInSphere(r) {
    let x, y, z, d;
    do {
      x = (Math.random() * 2 - 1);
      y = (Math.random() * 2 - 1);
      z = (Math.random() * 2 - 1);
      d = x * x + y * y + z * z;
    } while (d > 1 || d === 0);
    const s = r * Math.cbrt(Math.random());
    return new THREE.Vector3(x, y, z).normalize().multiplyScalar(s);
  }

  const center = new THREE.Vector3(0, 0, -1.5);

  // ---------- field particles ----------
  const fieldGeo = new THREE.IcosahedronGeometry(0.012, 0);
  const fieldOpacityUniform = uniform(1.0);

  const fieldOpacityAttr = new Float32Array(FIELD_COUNT);
  const fieldAnchors = [];

  const fieldMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(0xe8ecf2),
    metalness: 0.0,
    roughness: 1.0,
    emissive: new THREE.Color(0xe8ecf2),
    emissiveIntensity: 0.0,
    transparent: true,
  });

  const fieldMesh = new THREE.InstancedMesh(fieldGeo, fieldMaterial, FIELD_COUNT);
  fieldMesh.name = 'FieldParticles';

  const dummy = new THREE.Object3D();
  const distances = [];
  let maxDist = 0;

  for (let i = 0; i < FIELD_COUNT; i++) {
    const anchor = randInEllipsoid(3, 2, 2.5).add(center);
    fieldAnchors.push(anchor);
    const dz = anchor.z; // depth from 0
    const t = THREE.MathUtils.clamp((0 - dz) / 5, 0, 1); // 0 at z=0, 1 at z=-5
    const opacity = THREE.MathUtils.lerp(0.9, 0.15, t);
    fieldOpacityAttr[i] = opacity;

    dummy.position.copy(anchor);
    dummy.scale.setScalar(0.001);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);

    const d = anchor.distanceTo(new THREE.Vector3(0, 0, 0));
    distances.push(d);
    if (d > maxDist) maxDist = d;
  }
  fieldMesh.instanceMatrix.needsUpdate = true;

  const fieldOpacityAttrNode = new THREE.InstancedBufferAttribute(fieldOpacityAttr, 1);
  fieldGeo.setAttribute('instanceOpacity', fieldOpacityAttrNode);

  fieldMaterial.opacityNode = attribute('instanceOpacity').mul(fieldOpacityUniform);

  group.add(fieldMesh);

  // ---------- core particles ----------
  const coreGeo = new THREE.IcosahedronGeometry(0.012, 0);
  const coreEmissiveUniform = uniform(1.8);

  const coreMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(0xff2a38),
    metalness: 0.0,
    roughness: 1.0,
    emissive: new THREE.Color(0xff2a38),
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  coreMaterial.emissiveNode = color(0xff2a38).mul(coreEmissiveUniform);

  const coreMesh = new THREE.InstancedMesh(coreGeo, coreMaterial, CORE_COUNT);
  coreMesh.name = 'CoreParticles';

  const coreAnchors = [];
  for (let i = 0; i < CORE_COUNT; i++) {
    const anchor = randInSphere(0.5);
    coreAnchors.push(anchor);
    dummy.position.copy(anchor);
    dummy.scale.setScalar(0.001);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  // ---------- fog (linear, near 4, far 10) ----------
  group.traverse((obj) => {});
  // Note: scene fog is typically set at scene level; apply as node material mix here optionally skipped.

  // ---------- particle-emerge primitive ----------
  const emergeParams = (config.cinematicPrimitives || []).find(p => p.name === 'particle-emerge')?.params || { count: 1200, durationMs: 1400 };
  if (ctx.primitives && ctx.primitives['particle-emerge']) {
    ctx.primitives['particle-emerge'](fieldMesh, emergeParams);
    ctx.primitives['particle-emerge'](coreMesh, emergeParams);
  }

  // manual emerge fallback / stagger animation driving scale+position from core to anchor
  const dur = (emergeParams.durationMs || 1400) / 1000;

  function animateEmerge(mesh, anchors, dists, maxD) {
    const m = new THREE.Object3D();
    for (let i = 0; i < anchors.length; i++) {
      const anchor = anchors[i];
      const dNorm = maxD > 0 ? (dists ? dists[i] / maxD : 0) : 0;
      const delay = dNorm * 0.4;
      const state = { t: 0 };
      const tl = gsap.timeline({ delay });
      tl.to(state, {
        t: 1,
        duration: dur,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onUpdate: () => {
          m.position.lerpVectors(new THREE.Vector3(0, 0, 0), anchor, state.t);
          m.scale.setScalar(Math.max(0.001, state.t));
          m.updateMatrix();
          mesh.setMatrixAt(i, m.matrix);
          mesh.instanceMatrix.needsUpdate = true;
        },
      });
      timelines.push(tl);
    }
  }
  animateEmerge(fieldMesh, fieldAnchors, distances, maxDist);
  animateEmerge(coreMesh, coreAnchors, null, 0);

  // ---------- ambient drift + core pulse via clock update ----------
  const phases = fieldAnchors.map(() => Math.random() * Math.PI * 2);
  const corePhases = coreAnchors.map(() => Math.random() * Math.PI * 2);
  const driftDummy = new THREE.Object3D();
  const clock = new THREE.Clock();
  let rafActive = true;

  function tick() {
    if (!rafActive) return;
    const t = clock.getElapsedTime();

    for (let i = 0; i < fieldAnchors.length; i++) {
      const anchor = fieldAnchors[i];
      const ph = phases[i];
      const off = Math.sin(t * 0.05 * Math.PI * 2 + ph) * 0.04;
      driftDummy.position.set(anchor.x + off, anchor.y + off * 0.7, anchor.z + off * 0.5);
      driftDummy.scale.setScalar(1);
      driftDummy.updateMatrix();
      fieldMesh.setMatrixAt(i, driftDummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < coreAnchors.length; i++) {
      const anchor = coreAnchors[i];
      const ph = corePhases[i];
      const off = Math.sin(t * 0.05 * Math.PI * 2 + ph) * 0.04;
      driftDummy.position.set(anchor.x + off, anchor.y + off * 0.7, anchor.z + off * 0.5);
      driftDummy.scale.setScalar(1);
      driftDummy.updateMatrix();
      coreMesh.setMatrixAt(i, driftDummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;

    const pulse = 1.5 + (Math.sin(t * 0.1 * Math.PI * 2) * 0.5 + 0.5) * 0.3;
    coreEmissiveUniform.value = pulse;

    requestId = requestAnimationFrame(tick);
  }
  let requestId = requestAnimationFrame(tick);

  // ---------- lights ----------
  const ambient = new THREE.AmbientLight(0xe8ecf2, 0.3);
  group.add(ambient);
  const point = new THREE.PointLight(0xff2a38, 1.2, 8, 2);
  point.position.set(0, 0, 0.5);
  group.add(point);

  // ---------- text ----------
  const heroText = ctx.fontAtlas.createText({
    text: 'NOVA ATELIER',
    font: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.02,
    color: '#e8ecf2',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText({
    text: 'Precision instruments for the dark hours.',
    font: 'JetBrains Mono',
    fontSize: 40,
    fontWeight: 400,
    letterSpacing: 0.02,
    lineHeight: 1.35,
    color: '#e8ecf2',
  });
  subheadText.position.set(0, 0.5 - 0.75, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText({
    text: 'EST. 2019 / GENEVA AND KYOTO',
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#ff2a38',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // ---------- userData ----------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    rafActive = false;
    if (requestId) cancelAnimationFrame(requestId);
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    fieldGeo.dispose();
    coreGeo.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();
    fieldMesh.dispose && fieldMesh.dispose();
    coreMesh.dispose && coreMesh.dispose();

    [heroText, subheadText, captionText].forEach((t) => {
      if (t.userData && t.userData.cleanup) t.userData.cleanup();
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    });
  };

  return group;
}
